window.kbPageData["views/entry/k-6e072ace017bc8e0"] = {"key":"entry/k-6e072ace017bc8e0","state":{"route":"entry/k-6e072ace017bc8e0"},"node":{"id":"k-6e072ace017bc8e0","mode":"k","title":"魏源论法令的可行性","type":"观点与论证","domain":"法律","reading":"","intro":"","priority":100,"aliases":["法律有效施行有赖于符合社会实际与人情"],"qs":["江苏 2024 A类 行测#6"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"魏源认为，强求人去做能力所不及的事，事情难以办成。以法令禁止人们必然会做的事，法令也难以施行。","review":{"definition":"魏源认为，强求人去做能力所不及的事，事情难以办成。以法令禁止人们必然会做的事，法令也难以施行。","explanation":"魏源用“所不能”和“所必犯”指出法令能否施行取决于它是否顾及人的实际能力和行为。A项强调法律应当顾及天理人情，与这一主张最接近。B项讲法律如何塑造习惯，C项讲国家强制力如何保障法律实施，D项讲法律效力对合法事物的支撑。","references":[],"evidence":"强人之所不能，事必不立；禁人之所必犯，法必不行。","disposition":"题内说明","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#6":{"paper":"江苏 2024 A类 行测","n":6,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",2],"card":"2c0ab6613fa975062794f32e","links":[{"id":"k-6e072ace017bc8e0","role":"直接考查","why":"规则若要求人们履行实际上无法履行的义务，或禁止人们必然会实施的行为，就难以施行。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-6e072ace017bc8e0":[["江苏 2024 A类 行测#6"]]}};
